"""A Class for performing sequenced interactions to login in on a MONACO application"""

from ..interactions import MonacoLoginFuncs


class Login():
    def __init__(self) -> None:
        pass

    def loginUser(self, username: str, password: str) -> None:
        MonacoLoginFuncs.enter_username(username)
        MonacoLoginFuncs.enter_password(password)
        MonacoLoginFuncs.click_login_button()
